  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--text-main);
  background-color: var(--c-white);
  line-height: 1.5;
  overflow-x: hidden;
}

img, svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Utilities */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--sp-lg);
}

.bg-alt {
  background-color: var(--c-surface);
}

.text-center {
  text-align: center;
}

/* Typography */
h1, h2, h3, h4 {
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.hero-title {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  margin-bottom: var(--sp-lg);
  background: var(--grad-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  padding-bottom: 0.1em;
}

.hero-subtitle {
  font-size: clamp(1.125rem, 2vw, 1.25rem);
  color: var(--text-muted);
  margin-bottom: var(--sp-xl);
  max-width: 600px;
  font-weight: 500;
}

.section-title {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: var(--sp-lg);
}

.section-title.sm {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  margin-bottom: 0;
}

.section-desc {
  font-size: 1.125rem;
  color: var(--text-muted);
  margin-bottom: var(--sp-xl);
  font-weight: 500;
}

.arrow {
  display: inline-block;
  transition: transform 0.3s ease;
}

a:hover .arrow {
  transform: translateX(4px);
}

/* Buttons & Links */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: var(--rad-pill);
  font-weight: 700;
  transition: all 0.3s ease;
  cursor: pointer;
  border: none;
}

.btn-primary {
  background-color: var(--c-black);
  color: var(--c-white);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 20px oklch(15% 0.01 285 / 15%);
}

.btn-gradient {
  background: var(--grad-brand);
  color: var(--c-white);
  padding: 16px 32px;
  font-size: 1.125rem;
}

.btn-gradient:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 0 15px 30px oklch(55% 0.25 280 / 25%);
}

.btn-outline {
  border: 2px solid var(--c-black);
  background: transparent;
  color: var(--c-black);
}

.btn-outline:hover {
  background: var(--c-black);
  color: var(--c-white);
}

.btn-store {
  background-color: var(--c-black);
  color: var(--c-white);
  padding: 16px 32px;
  font-size: 1.125rem;
}
.btn-store:hover {
  background-color: oklch(25% 0.01 285);
}

.text-link {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--c-purple);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* Header */
.site-header {
  position: fixed;
  top: 0;
  width: 100%;
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  z-index: 100;
  border-bottom: 1px solid oklch(90% 0.01 280);
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.05em;
  background: var(--grad-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: var(--sp-lg);
}

.nav-link {
  font-weight: 600;
  color: var(--text-main);
  transition: color 0.2s;
}

.nav-link:hover {
  color: var(--c-purple);
}

.hamburger-btn {
  display: none;
  flex-direction: column;
  gap: 6px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}

.hamburger-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--c-black);
  transition: 0.3s;
}

@media (max-width: 768px) {
  .desktop-nav { display: none; }
  .hamburger-btn { display: flex; }
}

/* Mobile Menu */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--c-white);
  z-index: 200;
  transform: translateY(-100%);
  transition: transform 0.4s cubic-bezier(0.85, 0, 0.15, 1);
  display: flex;
  flex-direction: column;
}

.mobile-menu.active {
  transform: translateY(0);
}

.mobile-menu-inner {
  padding: var(--sp-lg);
  display: flex;
  flex-direction: column;
  height: 100%;
}

.mobile-menu-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
  margin-top: -var(--sp-lg);
  margin-bottom: var(--sp-2xl);
}

.close-menu-btn {
  background: none;
  border: none;
  font-size: 2rem;
  cursor: pointer;
  color: var(--c-black);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: var(--sp-xl);
  font-size: 2rem;
  font-weight: 700;
}

.mt-4 { margin-top: var(--sp-xl); }

/* Layouts */
.section {
  padding: var(--sp-4xl) 0;
}

.grid-2-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-3xl);
}

.align-center {
  align-items: center;
}

@media (max-width: 992px) {
  .grid-2-col {
    grid-template-columns: 1fr;
    gap: var(--sp-2xl);
  }
  .reverse-mobile {
    display: flex;
    flex-direction: column-reverse;
  }
}

/* Hero Section */
.hero {
  padding: calc(80px + var(--sp-4xl)) 0 var(--sp-4xl);
  overflow: hidden;
}

.hero-visual {
  position: relative;
  height: 500px;
  border-radius: var(--rad-xl);
  background: var(--c-surface);
  display: flex;
  align-items: center;
  justify-content: center;
}

.abstract-shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0.6;
  z-index: 1;
}

.shape-1 {
  width: 300px;
  height: 300px;
  background: var(--c-purple);
  top: -50px;
  right: -50px;
}

.shape-2 {
  width: 250px;
  height: 250px;
  background: var(--c-orange);
  bottom: -20px;
  left: 20px;
}

.ui-mockup {
  position: relative;
  z-index: 2;
  width: 260px;
  height: 420px;
  background: var(--c-white);
  border-radius: var(--rad-lg);
  box-shadow: 0 25px 50px oklch(15% 0.01 285 / 10%);
  display: flex;
  flex-direction: column;
  padding: var(--sp-md);
  gap: var(--sp-md);
}

.mockup-header {
  display: flex;
  align-items: center;
  gap: var(--sp-sm);
}

.mockup-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--grad-brand);
}

.mockup-text {
  width: 80px;
  height: 12px;
  border-radius: var(--rad-pill);
  background: var(--c-surface);
}

.mockup-body {
  flex: 1;
  border-radius: var(--rad-md);
  background: oklch(90% 0.01 280);
  background-image: var(--grad-brand);
  opacity: 0.1;
}

.mockup-footer {
  display: flex;
  justify-content: space-around;
}

.mockup-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--c-surface);
}

/* Features Section */
.bento-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-md);
  aspect-ratio: 1;
}

.bento-item {
  border-radius: var(--rad-lg);
  padding: var(--sp-md);
  font-weight: 700;
  display: flex;
  align-items: flex-end;
  font-size: 1.25rem;
  color: var(--c-white);
}

.bento-clips { background: var(--c-purple); grid-column: span 2; }
.bento-stories { background: var(--c-orange); }
.bento-dms { background: var(--c-magenta); }
.bento-explore { background: var(--c-black); grid-column: span 2; }

/* Safety Section */
.visual-safety {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 400px;
}

.safety-shield {
  width: 160px;
  height: 180px;
  background: var(--grad-brand);
  border-radius: 20px 20px 80px 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 2;
  box-shadow: 0 20px 40px oklch(55% 0.25 280 / 20%);
}

.shield-check {
  width: 60px;
  height: 60px;
  background: var(--c-white);
  border-radius: 50%;
  position: relative;
}

.shield-check::after {
  content: '';
  position: absolute;
  top: 40%;
  left: 50%;
  width: 8px;
  height: 16px;
  border: solid var(--c-black);
  border-width: 0 3px 3px 0;
  transform: translate(-50%, -50%) rotate(45deg);
}

.safety-cards {
  position: absolute;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.s-card {
  position: absolute;
  background: var(--c-white);
  padding: 12px 24px;
  border-radius: var(--rad-pill);
  font-weight: 700;
  box-shadow: 0 10px 20px oklch(15% 0.01 285 / 5%);
}

.sc-1 { top: 20%; left: 0; transform: rotate(-5deg); }
.sc-2 { bottom: 20%; right: 0; transform: rotate(5deg); }

/* Creators Section */
.visual-creators {
  position: relative;
  height: 400px;
}

.creator-card {
  position: absolute;
  width: 180px;
  height: 240px;
  border-radius: var(--rad-lg);
  background: var(--c-surface);
  box-shadow: 0 15px 30px oklch(15% 0.01 285 / 10%);
}

.c-1 { top: 20px; left: 10%; background: var(--c-purple); transform: rotate(-10deg); z-index: 1; }
.c-2 { top: 60px; left: 30%; background: var(--c-magenta); transform: rotate(0); z-index: 3; }
.c-3 { top: 100px; right: 10%; background: var(--c-orange); transform: rotate(10deg); z-index: 2; }

/* Banner Section */
.section-banner {
  background: var(--grad-brand);
  color: var(--c-white);
  text-align: center;
  padding: var(--sp-4xl) var(--sp-lg);
}

.banner-text {
  font-size: clamp(2.5rem, 6vw, 5rem);
  max-width: 1000px;
  margin: 0 auto;
}

/* News Carousel */
.news-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: var(--sp-2xl);
}

.section-label {
  font-weight: 700;
  color: var(--c-purple);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--sp-sm);
  display: block;
}

@media (max-width: 600px) {
  .news-header {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--sp-md);
  }
}

.news-carousel-container {
  margin: 0 calc(-1 * var(--sp-lg));
  padding: 0 var(--sp-lg);
}

.news-carousel {
  display: flex;
  gap: var(--sp-lg);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-bottom: var(--sp-lg);
  scrollbar-width: none; /* Firefox */
}

.news-carousel::-webkit-scrollbar {
  display: none; /* Chrome/Safari */
}

.news-card {
  flex: 0 0 350px;
  scroll-snap-align: start;
  background: var(--c-white);
  border-radius: var(--rad-lg);
  overflow: hidden;
  box-shadow: 0 4px 12px oklch(15% 0.01 285 / 5%);
  transition: transform 0.3s ease;
}

.news-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 24px oklch(15% 0.01 285 / 10%);
}

@media (max-width: 600px) {
  .news-card {
    flex: 0 0 280px;
  }
}

.card-thumb {
  height: 200px;
  background: var(--c-surface);
}
.thumb-1 { background: var(--c-purple); }
.thumb-2 { background: var(--c-orange); }
.thumb-3 { background: var(--c-magenta); }
.thumb-4 { background: var(--c-black); }

.card-content {
  padding: var(--sp-lg);
}

.card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: var(--sp-sm);
}

.tag {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--c-purple);
  background: oklch(55% 0.25 280 / 10%);
  padding: 4px 8px;
  border-radius: var(--rad-sm);
}

.card-title {
  font-size: 1.25rem;
  margin-bottom: var(--sp-md);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.card-date {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* CTA Download */
.section-cta {
  padding: var(--sp-4xl) 0;
}

.cta-title {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: var(--sp-sm);
}

.cta-subtitle {
  font-size: clamp(1.25rem, 3vw, 2rem);
  color: var(--text-muted);
  margin-bottom: var(--sp-2xl);
}

.cta-buttons {
  display: flex;
  gap: var(--sp-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* Footer */
.site-footer {
  background: var(--c-black);
  color: var(--c-white);
  padding: var(--sp-4xl) 0 var(--sp-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: var(--sp-2xl);
  margin-bottom: var(--sp-4xl);
}

.footer-heading {
  font-size: 1.125rem;
  margin-bottom: var(--sp-lg);
  color: oklch(70% 0.01 280);
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--sp-sm);
}

.footer-links a {
  color: oklch(90% 0.01 280);
  font-weight: 500;
  transition: color 0.2s;
}

.footer-links a:hover {
  color: var(--c-white);
}

.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: var(--sp-lg);
  padding-top: var(--sp-xl);
  border-top: 1px solid oklch(30% 0.01 280);
}

.footer-lang select {
  background: transparent;
  color: var(--c-white);
  border: 1px solid oklch(40% 0.01 280);
  padding: 8px 16px;
  border-radius: var(--rad-sm);
  font-family: inherit;
  font-size: 0.875rem;
  cursor: pointer;
}

.footer-lang select option {
  color: var(--c-black);
}

.footer-legal {
  display: flex;
  gap: var(--sp-lg);
  font-size: 0.875rem;
  color: oklch(70% 0.01 280);
}

.footer-legal a:hover {
  color: var(--c-white);
}

.footer-social {
  display: flex;
  gap: var(--sp-md);
}

.footer-social a {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: oklch(30% 0.01 280);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  transition: background 0.2s;
}

.footer-social a:hover {
  background: var(--c-white);
  color: var(--c-black);
}

@media (max-width: 768px) {
  .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }
}

